"""Broad exact search for a violation of naive-dominates-gate under true gains."""
import sys
import time
from fractions import Fraction as Q
from math import lcm

from spiral_ln.evaluation_feedback_multigen import (decaying_gain_schedule, drift_levels,
                                                    gate_threshold, naive_threshold,
                                                    _binomial_pmf)


def joint_kernel(items, candidates, levels, gain_law, threshold):
    """kernel[(c,i)] = list of ((c',i'), Fraction).  Uses the polynomial form
    sum_k F(j-1)^(k-1) F(j)^(K-k) for the first-max tie rule, so denominators
    stay powers of the binomial denominators."""
    top = len(levels) - 1
    kernel = {}
    per_level = {}
    for level in range(top + 1):
        parts = {m: _binomial_pmf(items, levels[min(top, level + m)]) for m in gain_law}
        mixture = [sum(gain_law[m] * parts[m][j] for m in gain_law) for j in range(items + 1)]
        cdf, running = [], Q(0)
        for mass in mixture:
            running += mass
            cdf.append(running)
        stay = [cdf[j] ** candidates for j in range(items + 1)]
        poly = []
        for j in range(items + 1):
            lo = cdf[j - 1] if j else Q(0)
            poly.append(sum(lo ** (k - 1) * cdf[j] ** (candidates - k) for k in range(1, candidates + 1)))
        per_level[level] = (parts, stay, poly)
    for level in range(top + 1):
        parts, stay, poly = per_level[level]
        for c in range(items + 1):
            cap = min(items, c + threshold[c])
            entries = [((c, level), stay[cap])]
            for j in range(cap + 1, items + 1):
                for m in gain_law:
                    prob = gain_law[m] * parts[m][j] * poly[j]
                    if prob:
                        entries.append(((j, min(top, level + m)), prob))
            kernel[(c, level)] = entries
    return kernel


def run_chain(items, candidates, p0, step, schedule, threshold, horizon, eps=Q(1, 10**9)):
    """Exact E[c_g]/n, E[p(i_g)] for g = 0..horizon (stopping early once the
    absorbed mass is >= 1 - eps), plus the exact limit."""
    levels = drift_levels(p0, step)
    top = len(levels) - 1
    absorbing = {(c, i) for c in range(items + 1) for i in range(top + 1) if c + threshold[c] >= items}
    init = {(c, 0): mass for c, mass in enumerate(_binomial_pmf(items, levels[0])) if mass}
    D0 = lcm(*[m.denominator for m in init.values()])
    cur = {x: int(m * D0) for x, m in init.items()}
    den = D0
    kernels = {}
    reported, true, absorbed = [], [], []

    def record():
        ec = sum(m * x[0] for x, m in cur.items())
        ep = sum(m * levels[x[1]] for x, m in cur.items())
        ab = sum(m for x, m in cur.items() if x in absorbing)
        reported.append(Q(ec, den) / items)
        true.append(ep / den)
        absorbed.append(Q(ab, den))

    record()
    stopped = None
    for g, law in enumerate(schedule[:horizon]):
        key = tuple(sorted(law.items()))
        if key not in kernels:
            k = joint_kernel(items, candidates, levels, law, threshold)
            D = lcm(*[p.denominator for entries in k.values() for _, p in entries])
            kernels[key] = (D, {x: [(y, int(p * D)) for y, p in entries] for x, entries in k.items()})
        D, kint = kernels[key]
        nxt = {}
        for x, m in cur.items():
            for y, kk in kint[x]:
                nxt[y] = nxt.get(y, 0) + m * kk
        cur = {x: m for x, m in nxt.items() if m}
        den *= D
        record()
        if absorbed[-1] >= 1 - eps:
            stopped = g + 1
            break
    return {"reported": reported, "true": true, "absorbed": absorbed, "stopped_at": stopped,
            "levels": levels}


def limit(items, candidates, p0, step, gain_law, threshold):
    """Exact g -> infinity expectations for a constant gain law via the DAG."""
    levels = drift_levels(p0, step)
    top = len(levels) - 1
    kernel = joint_kernel(items, candidates, levels, gain_law, threshold)
    ec, ep = {}, {}
    for c in range(items, -1, -1):
        for level in range(top + 1):
            x = (c, level)
            if c + threshold[c] >= items:
                ec[x], ep[x] = Q(c), levels[level]
                continue
            stay = [p for y, p in kernel[x] if y == x][0]
            leave = 1 - stay
            if leave == 0:
                ec[x], ep[x] = Q(c), levels[level]
                continue
            ec[x] = sum(p * ec[y] for y, p in kernel[x] if y != x) / leave
            ep[x] = sum(p * ep[y] for y, p in kernel[x] if y != x) / leave
    init = _binomial_pmf(items, levels[0])
    return (sum(init[c] * ec[(c, 0)] for c in range(items + 1)) / items,
            sum(init[c] * ep[(c, 0)] for c in range(items + 1)))


def main():
    horizon = 100
    laws = {"fixed": {1: Q(1)}, "two_point": {0: Q(3, 4), 1: Q(1, 4)}}
    cells = 0
    gens = 0
    violations = []
    t0 = time.perf_counter()
    for law_name in ("fixed", "two_point", "decaying"):
        for p0 in (Q(1, 4), Q(1, 2), Q(0)):
            for step in (Q(1, 16), Q(1, 8), Q(1, 4), Q(3, 8)):
                for items in (4, 8, 16):
                    for candidates in (1, 2, 4):
                        for z in (1, 2, 3):
                            if law_name == "decaying":
                                schedule = decaying_gain_schedule(horizon, Q(1, 4), Q(3, 4))
                            else:
                                schedule = [laws[law_name]] * horizon
                            thr_n, thr_g = naive_threshold(items), gate_threshold(items, z)
                            if thr_n == thr_g:
                                continue
                            a = run_chain(items, candidates, p0, step, schedule, thr_n, horizon)
                            b = run_chain(items, candidates, p0, step, schedule, thr_g, horizon)
                            G = min(len(a["reported"]), len(b["reported"]))
                            cells += 1
                            gens += G - 1
                            first = None
                            for g in range(G):
                                if a["reported"][g] < b["reported"][g] or a["true"][g] < b["true"][g]:
                                    first = g
                                    break
                            lim = None
                            if law_name != "decaying":
                                ln = limit(items, candidates, p0, step, laws[law_name], thr_n)
                                lg = limit(items, candidates, p0, step, laws[law_name], thr_g)
                                lim = (ln, lg)
                                if ln[0] < lg[0] or ln[1] < lg[1]:
                                    violations.append(("limit", law_name, p0, step, items, candidates, z, ln, lg))
                                    print("LIMIT VIOLATION", law_name, p0, step, items, candidates, z,
                                          [float(v) for v in ln], [float(v) for v in lg], flush=True)
                            if first is not None:
                                violations.append(("finite", law_name, p0, step, items, candidates, z, first,
                                                   a["reported"][first], b["reported"][first],
                                                   a["true"][first], b["true"][first]))
                                print("VIOLATION", law_name, p0, step, items, candidates, z, "g=", first,
                                      "Ec", float(a["reported"][first]), float(b["reported"][first]),
                                      "Ep", float(a["true"][first]), float(b["true"][first]), flush=True)
                            else:
                                print("ok", law_name, p0, step, items, candidates, z, "G", G - 1,
                                      "stop", a["stopped_at"], b["stopped_at"],
                                      "Ec", round(float(a["reported"][-1]), 6), round(float(b["reported"][-1]), 6),
                                      "Ep", round(float(a["true"][-1]), 6), round(float(b["true"][-1]), 6),
                                      "lim", None if lim is None else [[round(float(v), 6) for v in l] for l in lim],
                                      f"{time.perf_counter() - t0:.1f}s", flush=True)
    print("cells", cells, "generations", gens, "violations", len(violations))
    for v in violations:
        print(v)


if __name__ == "__main__":
    main()

