"""Test candidate cones on the naive kernel iterates P^k f and on the limit."""
import sys
sys.path.insert(0, r"C:\Users\patri\AppData\Local\Temp\claude\C--Users-patri-OneDrive-Documents-GitHub-Spiral\af5af8c1-0184-44ad-ab52-2aae8f4d54ac\scratchpad\dom_scripts")
from fractions import Fraction as Q
from search import joint_kernel
from spiral_ln.evaluation_feedback_multigen import drift_levels, gate_threshold, naive_threshold


def iterates(items, candidates, levels, law, threshold, f, kmax):
    kernel = joint_kernel(items, candidates, levels, law, threshold)
    states = list(kernel)
    cur = {x: f(x) for x in states}
    out = [cur]
    for _ in range(kmax):
        cur = {x: sum(p * cur[y] for y, p in kernel[x]) for x in states}
        out.append(cur)
    return kernel, out


def limit_values(items, levels, kernel, threshold, f):
    top = len(levels) - 1
    V = {}
    for c in range(items, -1, -1):
        for i in range(top + 1):
            x = (c, i)
            stay = [p for y, p in kernel[x] if y == x][0]
            if c + threshold[c] >= items or stay == 1:
                V[x] = f(x)
                continue
            V[x] = sum(p * V[y] for y, p in kernel[x] if y != x) / (1 - stay)
    return V


def check(items, candidates, p0, step, z, law, kmax=60):
    levels = drift_levels(p0, step)
    top = len(levels) - 1
    tn, tg = naive_threshold(items), gate_threshold(items, z)
    fs = {"count": lambda x: Q(x[0]), "p": lambda x: levels[x[1]]}
    res = {}
    for name, f in fs.items():
        kn, itn = iterates(items, candidates, levels, law, tn, f, kmax)
        kg, itg = iterates(items, candidates, levels, law, tg, f, kmax)
        Vn = limit_values(items, levels, kn, tn, f)
        Vg = limit_values(items, levels, kg, tg, f)
        funcs = list(enumerate(itn)) + [("lim", Vn)]
        firstA = firstM1 = firstM2 = None
        for k, h in funcs:
            # (A) gate cone
            okA = all(h[(c, i)] <= h[(j, min(top, i + 1))]
                      for c in range(items + 1) for i in range(top + 1)
                      for j in range(c + 1, min(items, c + tg[c]) + 1))
            okM1 = all(h[(c, i)] >= h[(c + 1, i)] for c in range(items) for i in range(top + 1))
            okM2 = all(h[(c, i)] <= h[(c, i + 1)] for c in range(items + 1) for i in range(top))
            if not okA and firstA is None:
                firstA = k
            if not okM1 and firstM1 is None:
                firstM1 = k
            if not okM2 and firstM2 is None:
                firstM2 = k
        # Q^k f <= P^k f at every state?
        firstQP = None
        for k in range(kmax + 1):
            if not all(itg[k][x] <= itn[k][x] for x in itn[k]):
                firstQP = k
                break
        limQP = all(Vg[x] <= Vn[x] for x in Vn)
        res[name] = {"A": firstA, "M1": firstM1, "M2": firstM2, "QP_every_state": firstQP, "QP_limit_every_state": limQP}
    return res


if __name__ == "__main__":
    law = {1: Q(1)}
    for p0 in (Q(1, 4), Q(0), Q(1, 2)):
        for step in (Q(1, 16), Q(1, 8), Q(1, 4), Q(3, 8)):
            for items in (4, 8, 16):
                for candidates in (1, 2, 4):
                    for z in (1, 2, 3):
                        r = check(items, candidates, p0, step, z, law, kmax=40)
                        print(p0, step, items, candidates, z, r, flush=True)

